-- 4. Questions (Topic 49: Security Networking Basics - 13 Questions)
INSERT INTO questions (id, topic_id, difficulty, type, question_text, options, correct_answer, explanation, status) VALUES
-- Simple
('60000000-0000-0000-0000-000000000801', '50000000-0000-0000-0000-000000000049', 'simple', 'mcq', 'What does "IP" stand for in networking?', '["Internal Protocol", "Internet Protocol", "Incoming Packet", "Intranet Piece"]', 'Internet Protocol', 'IP is the principal set of digital message formats and rules for exchanging messages between computers across a single network or a series of interconnected networks.', 'active'),
('60000000-0000-0000-0000-000000000802', '50000000-0000-0000-0000-000000000049', 'simple', 'mcq', 'Which port is used for HTTP traffic?', '["21", "22", "80", "443"]', '80', 'Port 80 is the default port for unencrypted web traffic.', 'active'),
('60000000-0000-0000-0000-000000000803', '50000000-0000-0000-0000-000000000049', 'simple', 'mcq', 'What is the purpose of a Firewall?', '["To cool down the server", "To monitor and control incoming and outgoing network traffic based on security rules", "To speed up the internet", "To store login passwords"]', 'To monitor and control incoming and outgoing network traffic based on security rules', 'Firewalls act as a barrier between a trusted internal network and untrusted external networks.', 'active'),
('60000000-0000-0000-0000-000000000804', '50000000-0000-0000-0000-000000000049', 'simple', 'mcq', 'What does "VPN" stand for?', '["Virtual Packet Network", "Virtual Private Network", "Variable Private Node", "Verified Public Network"]', 'Virtual Private Network', 'A VPN creates a safe and encrypted connection over a less secure network like the internet.', 'active'),
-- Intermediate
('60000000-0000-0000-0000-000000000805', '50000000-0000-0000-0000-000000000049', 'intermediate', 'mcq', 'What is "TCP" and how is it different from "UDP"?', '["TCP is for videos, UDP is for text", "TCP is connection-oriented and reliable, UDP is connectionless and faster", "UDP is more secure than TCP", "They are identical"]', 'TCP is connection-oriented and reliable, UDP is connectionless and faster', 'TCP guarantees delivery of packets, while UDP does not.', 'active'),
('60000000-0000-0000-0000-000000000806', '50000000-0000-0000-0000-000000000049', 'intermediate', 'mcq', 'What is a "DMZ" in network security?', '["A type of encryption", "A physical or logical subnetwork that contains and exposes an organization''s external-facing services to an untrusted, usually larger, network such as the Internet", "A database zone", "A specialized cooling area"]', 'A physical or logical subnetwork that contains and exposes an organization''s external-facing services to an untrusted, usually larger, network such as the Internet', 'DMZ adds an extra layer of security to an organization''s local area network.', 'active'),
('60000000-0000-0000-0000-000000000807', '50000000-0000-0000-0000-000000000049', 'intermediate', 'mcq', 'What is "ARP Poisoning"?', '["Eating bad food", "Redirecting IP addresses to a MAC address using spoofed messages", "Scaling the internet", "Deleting network logs"]', 'Redirecting IP addresses to a MAC address using spoofed messages', 'Address Resolution Protocol (ARP) poisoning is a type of attack where a hacker sends malicious ARP messages to a local area network.', 'active'),
('60000000-0000-0000-0000-000000000808', '50000000-0000-0000-0000-000000000049', 'intermediate', 'mcq', 'What does "NAT" (Network Address Translation) do?', '["Translates languages", "Remaps one IP address space into another, usually for private networks sharing a public IP", "Encrypts data", "Speeds up CPU"]', 'Remaps one IP address space into another, usually for private networks sharing a public IP', 'NAT allows multiple devices on a private network to share a single public IP address.', 'active'),
-- Expert
('60000000-0000-0000-0000-000000000809', '50000000-0000-0000-0000-000000000049', 'expert', 'mcq', 'Explain the 3-Way Handshake in TCP security.', '["Hi, Hello, Bye", "SYN, SYN-ACK, ACK", "Login, Password, Token", "Send, Wait, Finish"]', 'SYN, SYN-ACK, ACK', 'The TCP 3-way handshake is the process used in a regular network to make a connection between server and client.', 'active'),
('60000000-0000-0000-0000-000000000810', '50000000-0000-0000-0000-000000000049', 'expert', 'mcq', 'What is the "OSI Model" and which layer handles encryption usually?', '["A computer brand, Layer 1", "Open Systems Interconnection model, Layer 6 (Presentation)", "A security standard, Layer 7", "A network tool, Layer 3"]', 'Open Systems Interconnection model, Layer 6 (Presentation)', 'The Presentation layer is responsible for the delivery and formatting of information to the application layer.', 'active'),
('60000000-0000-0000-0000-000000000811', '50000000-0000-0000-0000-000000000049', 'expert', 'mcq', 'What is "BGP Hijacking"?', '["Stealing a computer", "Taking over groups of IP addresses by corrupting Internet routing tables", "A type of database attack", "A network virus"]', 'Taking over groups of IP addresses by corrupting Internet routing tables', 'BGP hijacking can redirect traffic through an attacker''s own networks.', 'active'),
('60000000-0000-0000-0000-000000000812', '50000000-0000-0000-0000-000000000049', 'expert', 'mcq', 'What is the purpose of "VLAN Hopping"?', '["Jumping between networks", "An attack where an attacker sends packets to a port which is not normally accessible from their VLAN", "Scaling the Wi-Fi", "Improving signal strength"]', 'An attack where an attacker sends packets to a port which is not normally accessible from their VLAN', 'VLAN hopping allows attackers to bypass network security configurations.', 'active'),
('60000000-0000-0000-0000-000000000813', '50000000-0000-0000-0000-000000000049', 'expert', 'mcq', 'Explain "Subnet Masking".', '["Hiding a computer", "A method used to divide an IP address into two parts: the network address and the host address", "A security mask", "A network filter"]', 'A method used to divide an IP address into two parts: the network address and the host address', 'Subnet masking helps in identifying which part of the IP address belongs to the network and which part to the host.', 'active');

-- Topic 50: Modern Cryptography (13 Questions)
INSERT INTO questions (id, topic_id, difficulty, type, question_text, options, correct_answer, explanation, status) VALUES
-- Simple
('60000000-0000-0000-0000-000000000814', '50000000-0000-0000-0000-000000000050', 'simple', 'mcq', 'What is "Cryptography"?', '["The study of ancient coins", "The practice and study of techniques for secure communication in the presence of third parties", "A type of database", "A network tool"]', 'The practice and study of techniques for secure communication in the presence of third parties', 'Cryptography is essential for protecting data privacy and integrity.', 'active'),
('60000000-0000-0000-0000-000000000815', '50000000-0000-0000-0000-000000000050', 'simple', 'mcq', 'What is "Symmetric Encryption"?', '["Using different keys for encryption and decryption", "Using the same key for both encryption and decryption", "No keys are used", "A type of network"]', 'Using the same key for both encryption and decryption', 'AES is a common symmetric encryption algorithm.', 'active'),
('60000000-0000-0000-0000-000000000816', '50000000-0000-0000-0000-000000000050', 'simple', 'mcq', 'What is "Asymmetric Encryption"?', '["Using the same key", "Using a pair of keys: a public key for encryption and a private key for decryption", "Using many keys", "A type of database"]', 'Using a pair of keys: a public key for encryption and a private key for decryption', 'RSA is a widely used asymmetric algorithm.', 'active'),
('60000000-0000-0000-0000-000000000817', '50000000-0000-0000-0000-000000000050', 'simple', 'mcq', 'What is a "Hash Function"?', '["A type of breakfast", "A mathematical algorithm that maps data of arbitrary size to a fixed-size bit string", "A physical key", "A network router"]', 'A mathematical algorithm that maps data of arbitrary size to a fixed-size bit string', 'Hash functions are often used for data integrity checks.', 'active'),
-- Intermediate
('60000000-0000-0000-0000-000000000818', '50000000-0000-0000-0000-000000000050', 'intermediate', 'mcq', 'What is "Digital Signature"?', '["A scan of your hand", "A mathematical scheme for demonstrating the authenticity of digital messages or documents", "A login password", "A network log"]', 'A mathematical scheme for demonstrating the authenticity of digital messages or documents', 'Digital signatures provide authentication and non-repudiation.', 'active'),
('60000000-0000-0000-0000-000000000819', '50000000-0000-0000-0000-000000000050', 'intermediate', 'mcq', 'What is the "PKI" (Public Key Infrastructure)?', '["A type of internet", "A set of roles, policies, and procedures needed to create, manage, distribute, and revoke digital certificates", "A billing plan", "A network rule"]', 'A set of roles, policies, and procedures needed to create, manage, distribute, and revoke digital certificates', 'PKI is the foundation for secure communication on the internet (HTTPS).', 'active'),
('60000000-0000-0000-0000-000000000820', '50000000-0000-0000-0000-000000000050', 'intermediate', 'mcq', 'What is "Salt" in the context of password hashing?', '["A food ingredient", "Random data that is used as an additional input to a one-way function that hashes data", "A type of encryption", "A security standard"]', 'Random data that is used as an additional input to a one-way function that hashes data', 'Salting prevents attackers from using precomputed tables (rainbow tables) to crack hashes.', 'active'),
('60000000-0000-0000-0000-000000000821', '50000000-0000-0000-0000-000000000050', 'intermediate', 'mcq', 'What is an "IV" (Initialization Vector)?', '["Intravenous", "A fixed-size input to a cryptographic primitive that is typically required to be random or pseudorandom", "An IAM role", "A network router"]', 'A fixed-size input to a cryptographic primitive that is typically required to be random or pseudorandom', 'IVs ensure that the same plaintext yields different ciphertext even with the same key.', 'active'),
-- Expert
('60000000-0000-0000-0000-000000000822', '50000000-0000-0000-0000-000000000050', 'expert', 'mcq', 'What is "Forward Secrecy"?', '["Knowing the future", "A property of secure communication protocols where a compromise of long-term keys does not compromise past session keys", "Fast encryption", "A type of network"]', 'A property of secure communication protocols where a compromise of long-term keys does not compromise past session keys', 'Forward secrecy is achieved using ephemeral keys in protocols like TLS.', 'active'),
('60000000-0000-0000-0000-000000000823', '50000000-0000-0000-0000-000000000050', 'expert', 'mcq', 'Explain "Elliptic Curve Cryptography" (ECC).', '["Drawing circles", "An approach to public-key cryptography based on the algebraic structure of elliptic curves over finite fields", "A type of database", "A network protocol"]', 'An approach to public-key cryptography based on the algebraic structure of elliptic curves over finite fields', 'ECC provides the same security as RSA but with smaller key sizes.', 'active'),
('60000000-0000-0000-0000-000000000824', '50000000-0000-0000-0000-000000000050', 'expert', 'mcq', 'What is a "Collision" in hashing?', '["A car crash", "Two different inputs producing the same output hash", "A network traffic jam", "A database error"]', 'Two different inputs producing the same output hash', 'Cryptographic hash functions aim to be collision-resistant.', 'active'),
('60000000-0000-0000-0000-000000000825', '50000000-0000-0000-0000-000000000050', 'expert', 'mcq', 'What is "Diffie-Hellman Key Exchange"?', '["A type of lock", "A method of securely exchanging cryptographic keys over a public channel", "A login system", "A cloud server"]', 'A method of securely exchanging cryptographic keys over a public channel', 'Diffie-Hellman allows two parties to establish a shared secret without ever meeting.', 'active'),
('60000000-0000-0000-0000-000000000826', '50000000-0000-0000-0000-000000000050', 'expert', 'mcq', 'Explain "Zero-Knowledge Proofs".', '["Knowing nothing", "A method by which one party can prove to another party that they know a value, without conveying any information apart from the fact that they know the value", "A type of exam", "A network security tool"]', 'A method by which one party can prove to another party that they know a value, without conveying any information apart from the fact that they know the value', 'Zero-knowledge proofs are used in many privacy-focused technologies.', 'active'),

-- Topic 51: OWASP Top 10 Web Vulnerabilities (13 Questions)
INSERT INTO questions (id, topic_id, difficulty, type, question_text, options, correct_answer, explanation, status) VALUES
-- Simple
('60000000-0000-0000-0000-000000000827', '50000000-0000-0000-0000-000000000051', 'simple', 'mcq', 'What does OWASP stand for?', '["Online Web Application Security Protocol", "Open Web Application Security Project", "Official Web App Security Plan", "Organization for Web and App Security"]', 'Open Web Application Security Project', 'OWASP is a nonprofit foundation that works to improve the security of software.', 'active'),
('60000000-0000-0000-0000-000000000828', '50000000-0000-0000-0000-000000000051', 'simple', 'mcq', 'What is "SQL Injection"?', '["Adding more space to a database", "An attack where malicious SQL statements are inserted into an entry field for execution", "A way to speed up queries", "A database backup method"]', 'An attack where malicious SQL statements are inserted into an entry field for execution', 'SQL injection can lead to unauthorized data access or modification.', 'active'),
('60000000-0000-0000-0000-000000000829', '50000000-0000-0000-0000-000000000051', 'simple', 'mcq', 'What is "XSS" (Cross-Site Scripting)?', '["A type of CSS", "A vulnerability where an attacker injects malicious scripts into content from otherwise trusted websites", "A network tool", "A database engine"]', 'A vulnerability where an attacker injects malicious scripts into content from otherwise trusted websites', 'XSS can be used to steal session cookies or deface websites.', 'active'),
('60000000-0000-0000-0000-000000000830', '50000000-0000-0000-0000-000000000051', 'simple', 'mcq', 'What is "Broken Access Control"?', '["A broken door handle", "A vulnerability where an application fails to enforce the principle of least privilege, allowing users to access unauthorized data", "A login error", "A network timeout"]', 'A vulnerability where an application fails to enforce the principle of least privilege, allowing users to access unauthorized data', 'Access control is essential for protecting sensitive functionality and data.', 'active'),
-- Intermediate
('60000000-0000-0000-0000-000000000831', '50000000-0000-0000-0000-000000000051', 'intermediate', 'mcq', 'What is "CSRF" (Cross-Site Request Forgery)?', '["An email attachment", "An attack that forces an authenticated user to execute unwanted actions on a web application in which they are currently authenticated", "A type of encryption", "A network policy"]', 'An attack that forces an authenticated user to execute unwanted actions on a web application in which they are currently authenticated', 'CSRF targets state-changing requests.', 'active'),
('60000000-0000-0000-0000-000000000832', '50000000-0000-0000-0000-000000000051', 'intermediate', 'mcq', 'What is "Security Misconfiguration"?', '["Setting the wrong screen time", "When security settings are not defined, implemented, or maintained correctly", "A type of UI layout", "A programming error in JS"]', 'When security settings are not defined, implemented, or maintained correctly', 'Common misconfigurations include default accounts, open cloud storage, or verbose error messages.', 'active'),
('60000000-0000-0000-0000-000000000833', '50000000-0000-0000-0000-000000000051', 'intermediate', 'mcq', 'What is "Cryptographic Failure"?', '["Forget your password", "The compromise of sensitive data due to weak or absent cryptographic controls", "A type of math error", "A broken network cable"]', 'The compromise of sensitive data due to weak or absent cryptographic controls', 'Examples include using old algorithms like MD5 or plain text storage of passwords.', 'active'),
('60000000-0000-0000-0000-000000000834', '50000000-0000-0000-0000-000000000051', 'intermediate', 'mcq', 'What is "Insecure Design"?', '["A website that looks bad", "A broad category representing different weaknesses, where the security is not thought of from the beginning", "A type of CSS", "A small database"]', 'A broad category representing different weaknesses, where the security is not thought of from the beginning', 'Insecure design cannot be fixed with a narrow implementation change.', 'active'),
-- Expert
('60000000-0000-0000-0000-000000000835', '50000000-0000-0000-0000-000000000051', 'expert', 'mcq', 'What is "SSRF" (Server-Side Request Forgery)?', '["A type of DNS server", "When an attacker can abuse functionality on the server to read or update internal resources", "A type of encryption", "A network cable"]', 'When an attacker can abuse functionality on the server to read or update internal resources', 'SSRF often targets internal services that are not reachable from the outside.', 'active'),
('60000000-0000-0000-0000-000000000836', '50000000-0000-0000-0000-000000000051', 'expert', 'mcq', 'Explain "Insecure Deserialization".', '["Forget all settings", "The process where untrusted data is used to abuse the logic of an application", "A type of network attack", "A database backup error"]', 'The process where untrusted data is used to abuse the logic of an application', 'Deserialization can lead to remote code execution.', 'active'),
('60000000-0000-0000-0000-000000000837', '50000000-0000-0000-0000-000000000051', 'expert', 'mcq', 'What is the danger of "Using Components with Known Vulnerabilities"?', '["Using an old computer", "Integrating vulnerable libraries or frameworks into your product", "A type of UI issue", "A network fault"]', 'Integrating vulnerable libraries or frameworks into your product', 'Vulnerable components can provide an easy entry point for attackers.', 'active'),
('60000000-0000-0000-0000-000000000838', '50000000-0000-0000-0000-000000000051', 'expert', 'mcq', 'What are "Insufficient Logging and Monitoring"?', '["Not having a screen", "The lack of adequate visibility into ongoing security events and timely response", "A type of database error", "A small hard drive"]', 'The lack of adequate visibility into ongoing security events and timely response', 'Proper logging is crucial for incident detection and forensics.', 'active'),
('60000000-0000-0000-0000-000000000839', '50000000-0000-0000-0000-000000000051', 'expert', 'mcq', 'How can "MFA" failure lead to a Top 10 vulnerability?', '["By being easy to guess", "If MFA can be bypassed or is not enforced for administrative functions", "If the user loses their phone", "If the screen is too small"]', 'If MFA can be bypassed or is not enforced for administrative functions', 'Weak authentication can lead to full account compromise.', 'active'),

-- Topic 52: Penetration Testing Phases (13 Questions)
INSERT INTO questions (id, topic_id, difficulty, type, question_text, options, correct_answer, explanation, status) VALUES
-- Simple
('60000000-0000-0000-0000-000000000840', '50000000-0000-0000-0000-000000000052', 'simple', 'mcq', 'What is "Penetration Testing" (Pentesting)?', '["Testing the pens used in the office", "A simulated cyber attack against your computer system to check for exploitable vulnerabilities", "A type of database test", "A network speed test"]', 'A simulated cyber attack against your computer system to check for exploitable vulnerabilities', 'Pentesting is a proactive security assessment method.', 'active'),
('60000000-0000-0000-0000-000000000841', '50000000-0000-0000-0000-000000000052', 'simple', 'mcq', 'What is the "Reconnaissance" phase?', '["The last step", "The first step, involving gathering information about the target", "Exploiting the vulnerabilities", "Writing the report"]', 'The first step, involving gathering information about the target', 'Reconnaissance can be passive or active.', 'active'),
('60000000-0000-0000-0000-000000000842', '50000000-0000-0000-0000-000000000052', 'simple', 'mcq', 'What is "White Box Testing"?', '["Testing a white computer", "A method where the tester has full knowledge of the target system including source code", "A method where the tester has no knowledge", "A type of UI design"]', 'A method where the tester has full knowledge of the target system including source code', 'White box testing is also known as "glass box" or "structural" testing.', 'active'),
('60000000-0000-0000-0000-000000000843', '50000000-0000-0000-0000-000000000052', 'simple', 'mcq', 'What is "Black Box Testing"?', '["A system where the tester has no prior knowledge of the target", "Testing in a dark room", "A database test", "A network tool"]', 'A system where the tester has no prior knowledge of the target', 'Black box testing simulates an external attacker with no internal information.', 'active'),
-- Intermediate
('60000000-0000-0000-0000-000000000844', '50000000-0000-0000-0000-000000000052', 'intermediate', 'mcq', 'What is the "Scanning" phase in pentesting?', '["Scanning a document", "Using tools like Nmap to identify open ports and services on a target", "Exploiting the code", "Writing the summary"]', 'Using tools like Nmap to identify open ports and services on a target', 'Scanning is an active information gathering phase.', 'active'),
('60000000-0000-0000-0000-000000000845', '50000000-0000-0000-0000-000000000052', 'intermediate', 'mcq', 'What is "Vulnerability Assessment"?', '["Calculating the company budget", "The process of identifying and quantifying security vulnerabilities in an environment", "Hacking into a system", "A network policy"]', 'The process of identifying and quantifying security vulnerabilities in an environment', 'Assessments often provide a prioritized list of issues.', 'active'),
('60000000-0000-0000-0000-000000000846', '50000000-0000-0000-0000-000000000052', 'intermediate', 'mcq', 'What is "Gaining Access"?', '["Opening a door", "The act of actually exploiting a vulnerability to control target resources", "Reading a report", "Scanning for ports"]', 'The act of actually exploiting a vulnerability to control target resources', 'This happens after vulnerabilities have been identified.', 'active'),
('60000000-0000-0000-0000-000000000847', '50000000-0000-0000-0000-000000000052', 'intermediate', 'mcq', 'What is "Maintaining Access"?', '["Cleaning the server", "The phase where the attacker ensures they can return to the target system even after it has been rebooted or patched", "Logging out", "Fixing bugs"]', 'The phase where the attacker ensures they can return to the target system even after it has been rebooted or patched', 'Often involves backdoors or rootkits.', 'active'),
-- Expert
('60000000-0000-0000-0000-000000000848', '50000000-0000-0000-0000-000000000052', 'expert', 'mcq', 'Explain "Red Teaming" vs Pentesting.', '["Colors on a map", "Red teaming is a full-scope, objective-based simulation of real attacks; pentesting is more focused on finding as many vulnerabilities as possible", "They are identical", "Red teaming is easier"]', 'Red teaming is a full-scope, objective-based simulation of real attacks; pentesting is more focused on finding as many vulnerabilities as possible', 'Red team exercises often include physical security and social engineering.', 'active'),
('60000000-0000-0000-0000-000000000849', '50000000-0000-0000-0000-000000000052', 'expert', 'mcq', 'What is "Reporting and Analysis" in pentesting?', '["Deleting all files", "The final phase where the results are documented and recommendations for remediation are provided", "Hacking more systems", "Scanning for more ports"]', 'The final phase where the results are documented and recommendations for remediation are provided', 'This is the most critical phase for the organization to improve its security.', 'active'),
('60000000-0000-0000-0000-000000000850', '50000000-0000-0000-0000-000000000052', 'expert', 'mcq', 'What is "Post-Exploitation"?', '["Before hacking", "The phase after gaining access, where and attacker explores the system and tries to expand their control", "After fixing the bug", "A type of UI design"]', 'The phase after gaining access, where and attacker explores the system and tries to expand their control', 'Post-exploitation involves privilege escalation and lateral movement.', 'active'),
('60000000-0000-0000-0000-000000000851', '50000000-0000-0000-0000-000000000052', 'expert', 'mcq', 'What is "OSINT" (Open Source Intelligence)?', '["A type of operating system", "Data collected from publicly available sources to be used in an intelligence context", "Private database logs", "A network sniffer"]', 'Data collected from publicly available sources to be used in an intelligence context', 'OSINT is heavily used in the reconnaissance phase.', 'active'),
('60000000-0000-0000-0000-000000000852', '50000000-0000-0000-0000-000000000052', 'expert', 'mcq', 'Explain "Pivot" in the context of pentesting.', '["Turning a server", "Using one compromised system to gain access to other systems on the same or a different network", "Changing your email", "A type of database query"]', 'Using one compromised system to gain access to other systems on the same or a different network', 'Pivoting is key to lateral movement within a network.', 'active');

-- Topic 53: Incident Response Lifecycle (13 Questions)
INSERT INTO questions (id, topic_id, difficulty, type, question_text, options, correct_answer, explanation, status) VALUES
-- Simple
('60000000-0000-0000-0000-000000000853', '50000000-0000-0000-0000-000000000053', 'simple', 'mcq', 'What is an "Incident" in cyber security?', '["A scheduled update", "An event that could lead to loss of, or disruption to, an organization''s operations, services or functions", "A new employee joining", "A low battery warning"]', 'An event that could lead to loss of, or disruption to, an organization''s operations, services or functions', 'Incidents require a structured response to minimize damage.', 'active'),
('60000000-0000-0000-0000-000000000854', '50000000-0000-0000-0000-000000000053', 'simple', 'mcq', 'What is the "Preparation" phase in IR?', '["Hacking back", "Establishing the policies, procedures, and tools needed to respond to an incident", "Fixing the server after a hack", "Closing the ticket"]', 'Establishing the policies, procedures, and tools needed to respond to an incident', 'Preparation involves training, tool selection, and policy development.', 'active'),
('60000000-0000-0000-0000-000000000855', '50000000-0000-0000-0000-000000000053', 'simple', 'mcq', 'What is the goal of "Containment"?', '["To ignore the virus", "To limit the scope and magnitude of an incident", "To delete all data", "To buy new hardware"]', 'To limit the scope and magnitude of an incident', 'Containment prevents the threat from spreading further into the network.', 'active'),
('60000000-0000-0000-0000-000000000856', '50000000-0000-0000-0000-000000000053', 'simple', 'mcq', 'What does "CSIRT" stand for?', '["Computer Security Incident Response Team", "Cyber Service Intermediate Reset Tool", "Cloud Security Internal Review Team", "Centralized Security Incident Recovery Task"]', 'Computer Security Incident Response Team', 'CSIRT is the group responsible for responding to security incidents.', 'active'),
-- Intermediate
('60000000-0000-0000-0000-000000000857', '50000000-0000-0000-0000-000000000053', 'intermediate', 'mcq', 'What is the "Detection and Analysis" phase?', '["Buying new software", "Identifying that an incident has occurred and determining its nature and impact", "Deleting logs", "Sending a bill to the attacker"]', 'Identifying that an incident has occurred and determining its nature and impact', 'Analysis involves looking at logs, alerts, and system artifacts.', 'active'),
('60000000-0000-0000-0000-000000000858', '50000000-0000-0000-0000-000000000053', 'intermediate', 'mcq', 'What is "Eradication" in the IR lifecycle?', '["Turning off the power", "The removal of the roots of the incident, such as deleting malware or disabling compromised accounts", "Reinstalling the OS immediately", "Paying the ransom"]', 'The removal of the roots of the incident, such as deleting malware or disabling compromised accounts', 'Eradication ensures the primary cause of the incident is gone.', 'active'),
('60000000-0000-0000-0000-000000000859', '50000000-0000-0000-0000-000000000053', 'intermediate', 'mcq', 'What is the "Recovery" phase?', '["Going on vacation", "Restoring systems and services to normal operation", "Hiding the incident from the boss", "Closing the office"]', 'Restoring systems and services to normal operation', 'Recovery might involve restoring from backups and extensive testing.', 'active'),
('60000000-0000-0000-0000-000000000860', '50000000-0000-0000-0000-000000000053', 'intermediate', 'mcq', 'What are "Post-Incident Activity / Lessons Learned"?', '["A celebration", "Meeting to analyze the incident, what went well, and what could be improved for next time", "A type of database cleanup", "Updating the antivirus"]', 'Meeting to analyze the incident, what went well, and what could be improved for next time', 'Lessons learned help close the gap in the security posture.', 'active'),
-- Expert
('60000000-0000-0000-0000-000000000861', '50000000-0000-0000-0000-000000000053', 'expert', 'mcq', 'Explain "Ransomware" response best practices.', '["Paying the ransom quickly", "Isolating infected systems, validating backups, and refusing to pay unless absolutely necessary by legal advice", "Deleting everything", "Formating the network"]', 'Isolating infected systems, validating backups, and refusing to pay unless absolutely necessary by legal advice', 'Paying the ransom does not guarantee data recovery and encourages further attacks.', 'active'),
('60000000-0000-0000-0000-000000000862', '50000000-0000-0000-0000-000000000053', 'expert', 'mcq', 'What is "SIEM" (Security Information and Event Management) used for in IR?', '["A type of mouse", "Real-time analysis of security alerts generated by applications and network hardware", "A database for users", "A marketing tool"]', 'Real-time analysis of security alerts generated by applications and network hardware', 'SIEM provides centralized visibility and correlation of security events.', 'active'),
('60000000-0000-0000-0000-000000000863', '50000000-0000-0000-0000-000000000053', 'expert', 'mcq', 'What is "SOAR" (Security Orchestration, Automation, and Response)?', '["A bird", "A stack of compatible software programs that allow an organization to collect data about security threats and respond without human assistance", "A type of firewall", "A cloud region"]', 'A stack of compatible software programs that allow an organization to collect data about security threats and respond without human assistance', 'SOAR aims to streamline incident response workflows using automation.', 'active'),
('60000000-0000-0000-0000-000000000864', '50000000-0000-0000-0000-000000000053', 'expert', 'mcq', 'Explain the "OODA Loop" in cyber defense.', '["A circular network cable", "Observe, Orient, Decide, Act - a four-stage cycle for making decisions in uncertain environments", "A type of programming loop", "A security standard"]', 'Observe, Orient, Decide, Act - a four-stage cycle for making decisions in uncertain environments', 'The OODA loop is used to out-maneuver attackers by responding faster than they can adapt.', 'active'),
('60000000-0000-0000-0000-000000000865', '50000000-0000-0000-0000-000000000053', 'expert', 'mcq', 'What is a "Playbook" in Incident Response?', '["A book for actors", "A set of standardized, documented procedures for responding to specific types of security incidents", "A database of logs", "A network routing table"]', 'A set of standardized, documented procedures for responding to specific types of security incidents', 'Playbooks ensure that responses are consistent and follow best practices.', 'active');

-- Topic 54: Digital Forensics Fundamentals (13 Questions)
INSERT INTO questions (id, topic_id, difficulty, type, question_text, options, correct_answer, explanation, status) VALUES
-- Simple
('60000000-0000-0000-0000-000000000866', '50000000-0000-0000-0000-000000000054', 'simple', 'mcq', 'What is "Digital Forensics"?', '["Repairing broken computers", "The field of forensic science that deals with the recovery and investigation of material found in digital devices", "A type of UI design", "Writing code for security"]', 'The field of forensic science that deals with the recovery and investigation of material found in digital devices', 'Digital forensics is used in criminal investigations and incident response.', 'active'),
('60000000-0000-0000-0000-000000000867', '50000000-0000-0000-0000-000000000054', 'simple', 'mcq', 'What is the "Chain of Custody"?', '["A type of encryption", "The chronological documentation that records the sequence of custody, control, transfer, analysis, and disposition of evidence", "A login system", "A network rule"]', 'The chronological documentation that records the sequence of custody, control, transfer, analysis, and disposition of evidence', 'Maintaining the chain of custody is essential for evidence to be admissible in court.', 'active'),
('60000000-0000-0000-0000-000000000868', '50000000-0000-0000-0000-000000000054', 'simple', 'mcq', 'What is "Volatile Data"?', '["Data that changes randomly", "Data that is lost when power is removed from the device", "Encrypted data", "Big data"]', 'Data that is lost when power is removed from the device', 'Examples of volatile data include RAM contents and network connection states.', 'active'),
('60000000-0000-0000-0000-000000000869', '50000000-0000-0000-0000-000000000054', 'simple', 'mcq', 'What is a "Write Blocker"?', '["A type of keyboard", "A device that allows data to be read from a drive but prevents any data from being written to it", "A slow network", "A firewall"]', 'A device that allows data to be read from a drive but prevents any data from being written to it', 'Write blockers preserve the integrity of original evidence during the imaging process.', 'active'),
-- Intermediate
('60000000-0000-0000-0000-000000000870', '50000000-0000-0000-0000-000000000054', 'intermediate', 'mcq', 'What is an "Image" in digital forensics?', '["A photo taken with a camera", "A bit-by-bit copy of a storage medium", "A type of icon", "A database backup"]', 'A bit-by-bit copy of a storage medium', 'Investigators always work on a copy (image) of the evidence, never the original.', 'active'),
('60000000-0000-0000-0000-000000000871', '50000000-0000-0000-0000-000000000054', 'intermediate', 'mcq', 'What is "Slack Space"?', '["Extra time in a project", "The space between the end of a file and the end of the last cluster assigned to that file", "A type of UI padding", "A network buffer"]', 'The space between the end of a file and the end of the last cluster assigned to that file', 'Slack space can contain hidden data or remnants of deleted files.', 'active'),
('60000000-0000-0000-0000-000000000872', '50000000-0000-0000-0000-000000000054', 'intermediate', 'mcq', 'What is "Hashing" used for in forensics?', '["To speed up search", "To verify the integrity of digital evidence and ensure it has not been tampered with", "To encrypt the files", "To hide the evidence"]', 'To verify the integrity of digital evidence and ensure it has not been tampered with', 'If the hash of an image matches the hash of the original device, the copy is verified.', 'active'),
('60000000-0000-0000-0000-000000000873', '50000000-0000-0000-0000-000000000054', 'intermediate', 'mcq', 'What is "Steganography"?', '["The study of old maps", "The practice of concealing messages or information within other non-secret text or data", "A type of programming language", "A network protocol"]', 'The practice of concealing messages or information within other non-secret text or data', 'Steganography is used to hide data in plain sight (e.g., inside an image file).', 'active'),
-- Expert
('60000000-0000-0000-0000-000000000874', '50000000-0000-0000-0000-000000000054', 'expert', 'mcq', 'Explain "Anti-Forensics".', '["Being against forensics", "Techniques used to thwart or mislead forensic analysis", "Deleting all files", "A type of firewall"]', 'Techniques used to thwart or mislead forensic analysis', 'Anti-forensics includes disk wiping, encryption, and log manipulation.', 'active'),
('60000000-0000-0000-0000-000000000875', '50000000-0000-0000-0000-000000000054', 'expert', 'mcq', 'What is "File Carving"?', '["Deleting a file", "The process of reassembling files from raw data by looking for specific file headers and footers", "Editing an image", "A type of database indexing"]', 'The process of reassembling files from raw data by looking for specific file headers and footers', 'File carving is used when file system metadata is missing or corrupted.', 'active'),
('60000000-0000-0000-0000-000000000876', '50000000-0000-0000-0000-000000000054', 'expert', 'mcq', 'What is the significance of the "Registry" in Windows forensics?', '["A list of users only", "A hierarchical database that stores configuration settings and options on Microsoft Windows OS", "A type of logs", "A network config file"]', 'A hierarchical database that stores configuration settings and options on Microsoft Windows OS', 'The registry contains wealth of information about user activity, software installation, and hardware connections.', 'active'),
('60000000-0000-0000-0000-000000000877', '50000000-0000-0000-0000-000000000054', 'expert', 'mcq', 'Explain "Unallocated Space".', '["Free memory in RAM", "Space on a hard drive that has not been divided into partitions or assigned to a file system", "A type of cloud storage", "A network buffer"]', 'Space on a hard drive that has not been divided into partitions or assigned to a file system', 'Unallocated space can contain fragments of previously existing files.', 'active'),
('60000000-0000-0000-0000-000000000878', '50000000-0000-0000-0000-000000000054', 'expert', 'mcq', 'What is "Live Forensics" vs "Dead Forensics"?', '["Testing a living computer vs a dead one", "Live forensics is performed while the system is powered on; Dead forensics is performed on a system that is powered off", "One is for users, one for servers", "A type of UI design"]', 'Live forensics is performed while the system is powered on; Dead forensics is performed on a system that is powered off', 'Live forensics allows for the collection of volatile data like network connections and RAM.', 'active');

-- Topic 55: Security Compliance Standards (13 Questions)
INSERT INTO questions (id, topic_id, difficulty, type, question_text, options, correct_answer, explanation, status) VALUES
-- Simple
('60000000-0000-0000-0000-000000000879', '50000000-0000-0000-0000-000000000055', 'simple', 'mcq', 'What is "Compliance" in cyber security?', '["Following all the rules in a game", "The act of following regulations, standards, or laws set by government or industry", "A type of software", "A login password"]', 'The act of following regulations, standards, or laws set by government or industry', 'Compliance helps ensure that organizations handle data responsibly.', 'active'),
('60000000-0000-0000-0000-000000000880', '50000000-0000-0000-0000-000000000055', 'simple', 'mcq', 'What does "GDPR" stand for?', '["General Data Protection Regulation", "Global Digital Privacy Rule", "Geographic Data Protection Requirement", "Government Data Privacy Record"]', 'General Data Protection Regulation', 'GDPR is a European union regulation on data protection and privacy.', 'active'),
('60000000-0000-0000-0000-000000000881', '50000000-0000-0000-0000-000000000055', 'simple', 'mcq', 'What is "HIPAA" related to?', '["Finances", "Health information privacy and security", "Education records", "Military data"]', 'Health information privacy and security', 'HIPAA protects sensitive patient health information.', 'active'),
('60000000-0000-0000-0000-000000000882', '50000000-0000-0000-0000-000000000055', 'simple', 'mcq', 'What is "PCI DSS"?', '["A type of printer", "Payment Card Industry Data Security Standard", "Private Cloud Infrastructure Standard", "Personal Computer Integration Standard"]', 'Payment Card Industry Data Security Standard', 'PCI DSS is for organizations that handle credit card information.', 'active'),
-- Intermediate
('60000000-0000-0000-0000-000000000883', '50000000-0000-0000-0000-000000000055', 'intermediate', 'mcq', 'What is "ISO 27001"?', '["A math constant", "An international standard for information security management systems", "A programming language", "A type of cloud bucket"]', 'An international standard for information security management systems', 'ISO 27001 provides a framework for managing information security risks.', 'active'),
('60000000-0000-0000-0000-000000000884', '50000000-0000-0000-0000-000000000055', 'intermediate', 'mcq', 'What is "SOC 2"?', '["A type of computer socket", "A reporting framework for service organizations that focuses on non-financial reporting controls", "A type of network switch", "A programming error"]', 'A reporting framework for service organizations that focuses on non-financial reporting controls', 'SOC 2 reports focus on security, availability, processing integrity, confidentiality, and privacy.', 'active'),
('60000000-0000-0000-0000-000000000885', '50000000-0000-0000-0000-000000000055', 'intermediate', 'mcq', 'What is "NIST" in the context of security standards?', '["National Institute of Standards and Technology", "Network Information Security Tool", "National Internet Standard Team", "None of the above"]', 'National Institute of Standards and Technology', 'NIST provides highly influential security frameworks and standards.', 'active'),
('60000000-0000-0000-0000-000000000886', '50000000-0000-0000-0000-000000000055', 'intermediate', 'mcq', 'What is a "PII"?', '["Personally Identifiable Information", "Public Internet Interface", "Private Instance Indicator", "Personal Identity ID"]', 'Personally Identifiable Information', 'PII is any data that can be used to identify a specific individual.', 'active'),
-- Expert
('60000000-0000-0000-0000-000000000887', '50000000-0000-0000-0000-000000000055', 'expert', 'mcq', 'Explain "CIS Benchmarks".', '["Performance tests for computers", "Best practice configuration standards for securely configuring a target system", "A database of users", "A marketing tool"]', 'Best practice configuration standards for securely configuring a target system', 'CIS Benchmarks are the industry-recognized standard for securing IT systems and data.', 'active'),
('60000000-0000-0000-0000-000000000888', '50000000-0000-0000-0000-000000000055', 'expert', 'mcq', 'What is "FERPA"?', '["A type of dog", "The Family Educational Rights and Privacy Act", "A health regulation", "A financial standard"]', 'The Family Educational Rights and Privacy Act', 'FERPA protects the privacy of student education records.', 'active'),
('60000000-0000-0000-0000-000000000889', '50000000-0000-0000-0000-000000000055', 'expert', 'mcq', 'What is the "FISMA"?', '["A type of fish", "The Federal Information Security Management Act", "A financial market standard", "A network routing protocol"]', 'The Federal Information Security Management Act', 'FISMA requires federal agencies to develop, document, and implement an agency-wide program to provide information security for information and information systems.', 'active'),
('60000000-0000-0000-0000-000000000890', '50000000-0000-0000-0000-000000000055', 'expert', 'mcq', 'What is "Auditing" in the context of compliance?', '["Counting money", "An official inspection of an individual''s or organization''s accounts, typically by an independent body", "A type of UI design", "Writing code for security"]', 'An official inspection of an individual''s or organization''s accounts, typically by an independent body', 'Auditing verifies that an organization is following its stated policies and procedures.', 'active'),
('60000000-0000-0000-0000-000000000891', '50000000-0000-0000-0000-000000000055', 'expert', 'mcq', 'Explain "Data Sovereignty".', '["Data control", "The concept that information which has been converted and stored in binary digital form is subject to the laws of the country in which it is located", "A type of encryption", "A cloud-based database"]', 'The concept that information which has been converted and stored in binary digital form is subject to the laws of the country in which it is located', 'Data sovereignty is a major consideration for global cloud deployments.', 'active');

-- Topic 56: Risk Management Frameworks (9 Questions)
INSERT INTO questions (id, topic_id, difficulty, type, question_text, options, correct_answer, explanation, status) VALUES
-- Simple
('60000000-0000-0000-0000-000000000892', '50000000-0000-0000-0000-000000000056', 'simple', 'mcq', 'What is "Risk" in cyber security?', '["A game", "The potential for loss, damage, or destruction of an asset as a result of a threat exploiting a vulnerability", "A type of software", "A login password"]', 'The potential for loss, damage, or destruction of an asset as a result of a threat exploiting a vulnerability', 'Risk management aims to identify and mitigate these potentials.', 'active'),
('60000000-0000-0000-0000-000000000893', '50000000-0000-0000-0000-000000000056', 'simple', 'mcq', 'What is a "Vulnerability"?', '["A strong wall", "A weakness in an information system, system security procedures, internal controls, or implementation that could be exploited by a threat", "A type of cloud", "A network router"]', 'A weakness in an information system, system security procedures, internal controls, or implementation that could be exploited by a threat', 'Vulnerabilities are the gaps that attackers seek to exploit.', 'active'),
('60000000-0000-0000-0000-000000000894', '50000000-0000-0000-0000-000000000056', 'simple', 'mcq', 'What is a "Threat"?', '["A gift", "A person or thing likely to cause damage or danger", "A database query", "A UI layout"]', 'A person or thing likely to cause damage or danger', 'Threats can be intentional (e.g., hackers) or unintentional (e.g., natural disasters).', 'active'),
-- Intermediate
('60000000-0000-0000-0000-000000000895', '50000000-0000-0000-0000-000000000056', 'intermediate', 'mcq', 'What is "Risk Assessment"?', '["Winning the lottery", "The process of identifying, estimating, and prioritizing risks to an organization''s operations", "Hacking into a system", "A network policy"]', 'The process of identifying, estimating, and prioritizing risks to an organization''s operations', 'Assessments help organizations decide how to allocate security resources.', 'active'),
('60000000-0000-0000-0000-000000000896', '50000000-0000-0000-0000-000000000056', 'intermediate', 'mcq', 'What is "Risk Mitigation"?', '["Ignoring the risk", "The implementation of security controls to reduce the likelihood or impact of a risk", "Hiding the data", "Paying for insurance"]', 'The implementation of security controls to reduce the likelihood or impact of a risk', 'Mitigation is a common risk response strategy.', 'active'),
('60000000-0000-0000-0000-000000000897', '50000000-0000-0000-0000-000000000056', 'intermediate', 'mcq', 'What is "Risk Acceptance"?', '["Being happy with everything", "The decision to take no action to reduce the likelihood or impact of a risk", "A type of password", "A network tool"]', 'The decision to take no action to reduce the likelihood or impact of a risk', 'Organizations might accept risk if the cost of mitigation is too high.', 'active'),
-- Expert
('60000000-0000-0000-0000-000000000898', '50000000-0000-0000-0000-000000000056', 'expert', 'mcq', 'What is "Residual Risk"?', '["A risk from the past", "The amount of risk that remains after all security controls have been implemented", "A type of cloud bucket", "A login error"]', 'The amount of risk that remains after all security controls have been implemented', 'Residual risk must be monitored and accepted by management.', 'active'),
('60000000-0000-0000-0000-000000000899', '50000000-0000-0000-0000-000000000056', 'expert', 'mcq', 'Explain "Risk Transfer".', '["Moving data", "The process of passing the risk to a third party, typically through insurance", "Deleting all files", "A network router"]', 'The process of passing the risk to a third party, typically through insurance', 'Cyber insurance is a common form of risk transfer.', 'active'),
('60000000-0000-0000-0000-000000000900', '50000000-0000-0000-0000-000000000056', 'expert', 'mcq', 'What is the "NIST Risk Management Framework" (RMF)?', '["A type of physical frame", "A 7-step process for managing risk through the system lifecycle", "A database of users", "A marketing tool"]', 'A 7-step process for managing risk through the system lifecycle', 'NIST RMF is widely used by government and regulated industries.', 'active');
